function canVisitAllRooms(rooms) {
    const n = rooms.length;
    const vis = Array(n).fill(false);
    const dfs = (i) => {
        if (vis[i]) {
            return;
        }
        vis[i] = true;
        for (const j of rooms[i]) {
            dfs(j);
        }
    };
    dfs(0);
    return vis.every(v => v);
}

